import React, {
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState
} from "react";

import Chart from "chart.js/auto";
import { marketIndices } from "./data";

import "./main.css";
import "./components.css";
import "./animations.css";
import "@fortawesome/fontawesome-free/css/all.min.css";

const API_BASE_URL = "http://localhost:5000/api";
const USER_ID = "testuser";

function App() {
  const [stocks, setStocks] = useState({});

  const [watchlist, setWatchlist] = useState([
    "RELIANCE",
    "TCS",
    "INFY"
  ]);

  const [filters, setFilters] = useState({
    search: "",
    sector: "",
    cap: ""
  });

  const [theme, setTheme] = useState(
    () => localStorage.getItem("theme") || "dark"
  );

  const [marketStatus, setMarketStatus] = useState("LIVE");
  const [updating, setUpdating] = useState(false);
  const [loading, setLoading] = useState(true);
  const [selectedStock, setSelectedStock] = useState(null);

  const [portfolio, setPortfolio] = useState({
    userId: USER_ID,
    cashBalance: 100000,
    holdings: []
  });

  const [transactions, setTransactions] = useState([]);
  const [tradeLoading, setTradeLoading] = useState(false);
  const [message, setMessage] = useState("");
  const [messageType, setMessageType] = useState("success");

  useEffect(() => {
    document.body.className =
      theme === "light" ? "light-theme" : "dark-theme";

    const root = document.documentElement;

    if (theme === "light") {
      root.style.setProperty("--bg-primary", "#ffffff");
      root.style.setProperty("--bg-secondary", "#f8f9fa");
      root.style.setProperty("--bg-tertiary", "#e9ecef");
      root.style.setProperty("--bg-panel", "#ffffff");
      root.style.setProperty("--text-primary", "#212529");
      root.style.setProperty("--text-secondary", "#6c757d");
      root.style.setProperty("--border-color", "#dee2e6");
    } else {
      root.style.setProperty("--bg-primary", "#0a0e1a");
      root.style.setProperty("--bg-secondary", "#1a1f35");
      root.style.setProperty("--bg-tertiary", "#242b42");
      root.style.setProperty("--bg-panel", "#1e2438");
      root.style.setProperty("--text-primary", "#e6e8ef");
      root.style.setProperty("--text-secondary", "#9ca3b4");
      root.style.setProperty("--border-color", "#2d3748");
    }
  }, [theme]);

  const showMessage = useCallback(
    (text, type = "success") => {
      setMessage(text);
      setMessageType(type);

      setTimeout(() => {
        setMessage("");
      }, 3500);
    },
    []
  );

  const fetchStocks = useCallback(async () => {
    try {
      const response = await fetch(
        `${API_BASE_URL}/stocks`
      );

      if (!response.ok) {
        throw new Error("Failed to fetch stocks");
      }

      const data = await response.json();

      setStocks((previousStocks) => {
        const formattedStocks = {};

        data.forEach((stock) => {
          const oldStock = previousStocks[stock.symbol];

          const newPoint = {
            time: new Date(
              stock.lastUpdated
            ).toLocaleTimeString(),
            price: Number(stock.price),
            volume: Number(stock.volume || 0)
          };

          formattedStocks[stock.symbol] = {
            symbol: stock.symbol,
            name: stock.name,
            price: Number(stock.price),
            change: Number(stock.change),
            changePercent: Number(stock.changePercent),
            volume: Number(stock.volume || 0),
            marketCap: Number(stock.marketCap || 0),
            sector: stock.sector || "Unknown",
            exchange: stock.exchange || "NSE",
            lastUpdated: stock.lastUpdated,
            dataSource: stock.dataSource,
            history: oldStock?.history
              ? [
                  ...oldStock.history.slice(-49),
                  newPoint
                ]
              : [newPoint]
          };
        });

        return formattedStocks;
      });

      setMarketStatus("LIVE");
    } catch (error) {
      console.error("Stock fetch error:", error);

      setMarketStatus("ERROR");

      showMessage(
        "Unable to connect to the stock API.",
        "error"
      );
    }
  }, [showMessage]);

  const fetchPortfolio = useCallback(async () => {
    try {
      const response = await fetch(
        `${API_BASE_URL}/portfolio/${USER_ID}`
      );

      if (!response.ok) {
        throw new Error("Failed to fetch portfolio");
      }

      const data = await response.json();

      setPortfolio(data);
    } catch (error) {
      console.error(
        "Portfolio fetch error:",
        error
      );
    }
  }, []);

  const fetchTransactions = useCallback(async () => {
    try {
      const response = await fetch(
        `${API_BASE_URL}/transactions/${USER_ID}`
      );

      if (!response.ok) {
        throw new Error(
          "Failed to fetch transactions"
        );
      }

      const data = await response.json();

      setTransactions(data);
    } catch (error) {
      console.error(
        "Transaction fetch error:",
        error
      );
    }
  }, []);

  useEffect(() => {
    const loadData = async () => {
      setLoading(true);

      await Promise.all([
        fetchStocks(),
        fetchPortfolio(),
        fetchTransactions()
      ]);

      setLoading(false);
    };

    loadData();
  }, [
    fetchStocks,
    fetchPortfolio,
    fetchTransactions
  ]);

  useEffect(() => {
    const interval = setInterval(() => {
      fetchStocks();
    }, 30000);

    return () => {
      clearInterval(interval);
    };
  }, [fetchStocks]);

  const refresh = async () => {
    if (updating) return;

    setUpdating(true);
    setMarketStatus("UPDATING");

    await fetchStocks();

    setUpdating(false);

    showMessage(
      "Stock data refreshed successfully."
    );
  };

  const addToWatchlist = (symbol) => {
    setWatchlist((previous) => {
      if (previous.includes(symbol)) {
        return previous;
      }

      return [...previous, symbol];
    });
  };

  const removeFromWatchlist = (symbol) => {
    setWatchlist((previous) =>
      previous.filter(
        (item) => item !== symbol
      )
    );
  };

  const buyStock = async (
    symbol,
    quantity
  ) => {
    const amount = Number(quantity);

    if (!amount || amount <= 0) {
      showMessage(
        "Enter a valid quantity.",
        "error"
      );
      return;
    }

    setTradeLoading(true);

    try {
      const response = await fetch(
        `${API_BASE_URL}/transactions/buy`,
        {
          method: "POST",

          headers: {
            "Content-Type":
              "application/json"
          },

          body: JSON.stringify({
            userId: USER_ID,
            symbol,
            quantity: amount
          })
        }
      );

      const data = await response.json();

      if (!response.ok) {
        throw new Error(
          data.message ||
            "Purchase failed"
        );
      }

      if (data.portfolio) {
        setPortfolio(
          data.portfolio
        );
      } else {
        await fetchPortfolio();
      }

      await fetchTransactions();

      showMessage(
        `Successfully bought ${amount} ${symbol} share(s).`
      );

      setSelectedStock(null);
    } catch (error) {
      console.error(
        "BUY error:",
        error
      );

      showMessage(
        error.message ||
          "Unable to buy stock.",
        "error"
      );
    } finally {
      setTradeLoading(false);
    }
  };

  const sellStock = async (
    symbol,
    quantity
  ) => {
    const amount = Number(quantity);

    if (!amount || amount <= 0) {
      showMessage(
        "Enter a valid quantity.",
        "error"
      );
      return;
    }

    setTradeLoading(true);

    try {
      const response = await fetch(
        `${API_BASE_URL}/transactions/sell`,
        {
          method: "POST",

          headers: {
            "Content-Type":
              "application/json"
          },

          body: JSON.stringify({
            userId: USER_ID,
            symbol,
            quantity: amount
          })
        }
      );

      const data = await response.json();

      if (!response.ok) {
        throw new Error(
          data.message ||
            "Sale failed"
        );
      }

      if (data.portfolio) {
        setPortfolio(
          data.portfolio
        );
      } else {
        await fetchPortfolio();
      }

      await fetchTransactions();

      showMessage(
        `Successfully sold ${amount} ${symbol} share(s).`
      );

      setSelectedStock(null);
    } catch (error) {
      console.error(
        "SELL error:",
        error
      );

      showMessage(
        error.message ||
          "Unable to sell stock.",
        "error"
      );
    } finally {
      setTradeLoading(false);
    }
  };

  const filteredStocks = useMemo(() => {
    let list = Object.entries(stocks);

    const search =
      filters.search
        .toLowerCase()
        .trim();

    if (search) {
      list = list.filter(
        ([symbol, stock]) =>
          stock.name
            .toLowerCase()
            .includes(search) ||
          symbol
            .toLowerCase()
            .includes(search) ||
          stock.sector
            .toLowerCase()
            .includes(search)
      );
    }

    if (filters.sector) {
      list = list.filter(
        ([, stock]) =>
          stock.sector ===
          filters.sector
      );
    }

    if (filters.cap) {
      list = list.filter(
        ([, stock]) => {
          const cap =
            Number(
              stock.marketCap || 0
            );

          if (
            filters.cap ===
            "large"
          ) {
            return (
              cap >=
              500000000000
            );
          }

          if (
            filters.cap ===
            "mid"
          ) {
            return (
              cap >=
                50000000000 &&
              cap <
                500000000000
            );
          }

          return (
            cap <
            50000000000
          );
        }
      );
    }

    return list;
  }, [stocks, filters]);

  const sectors = useMemo(() => {
    return [
      ...new Set(
        Object.values(stocks).map(
          (stock) =>
            stock.sector
        )
      )
    ];
  }, [stocks]);

  const stats = useMemo(() => {
    const values =
      Object.values(stocks);

    const total =
      values.length;

    const gainers =
      values.filter(
        (stock) =>
          stock.change > 0
      ).length;

    const losers =
      values.filter(
        (stock) =>
          stock.change < 0
      ).length;

    const averageVolume =
      total > 0
        ? values.reduce(
            (sum, stock) =>
              sum +
              Number(
                stock.volume || 0
              ),
            0
          ) /
          total /
          1000000
        : 0;

    return {
      total,
      gainers,
      losers,
      avgVol:
        averageVolume.toFixed(1)
    };
  }, [stocks]);

  const portfolioValue =
    useMemo(() => {
      return (
        portfolio.holdings || []
