function StockChart({ stock }) {
  const canvasRef =
    useRef(null);

  useEffect(() => {
    if (!canvasRef.current) {
      return;
    }

    const ctx =
      canvasRef.current.getContext(
        "2d"
      );

    const history =
      stock.history?.length
        ? stock.history
        : [
            {
              time:
                new Date().toLocaleTimeString(),
              price:
                stock.price
            }
          ];

    const color =
      stock.change >= 0
        ? "#10b981"
        : "#ef4444";

    const chart =
      new Chart(ctx, {
        type: "line",

        data: {
          labels:
            history.map(
              (item) =>
                item.time
            ),

          datasets: [
            {
              label:
                `${stock.symbol} Price`,

              data:
                history.map(
                  (item) =>
                    item.price
                ),

              borderColor:
                color,

              backgroundColor:
                `${color}20`,

              borderWidth: 2,

              fill: true,

              tension: 0.4,

              pointRadius: 2
            }
          ]
        },

        options: {
          responsive: true,

          maintainAspectRatio:
            false,

          plugins: {
            legend: {
              display: false
            },

            tooltip: {
              callbacks: {
                label: (
                  item
                ) =>
                  `₹${Number(
                    item.parsed.y
                  ).toFixed(2)}`
              }
            }
          },

          scales: {
            x: {
              display: false
            },

            y: {
              beginAtZero: false
            }
          }
        }
      });

    return () => {
      chart.destroy();
    };
  }, [stock]);

  return (
    <div className="panel">

      <div className="panel-header">

        <div>

          <h3>
            {stock.symbol}
          </h3>

          <span
            style={{
              fontSize: "12px",
              color:
                "var(--text-secondary)"
            }}
          >
            {stock.name}
          </span>

        </div>

        <div
          className={
            stock.change >= 0
              ? "positive"
              : "negative"
          }
        >
          ₹
          {stock.price.toFixed(
            2
          )}
        </div>

      </div>

      <div
        className="panel-body"
        style={{
          height: "220px"
        }}
      >

        <canvas
          ref={canvasRef}
        />

      </div>

    </div>
  );
}

function TradeModal({
  stock,
  onClose,
  onBuy,
  onSell,
  loading,
  isInWatchlist,
  onAddWatchlist,
  onRemoveWatchlist
}) {
  const [quantity, setQuantity] =
    useState(1);

  const [action, setAction] =
    useState("BUY");

  const total =
    stock.price *
    Number(
      quantity || 0
    );

  const submit = () => {
    if (action === "BUY") {
      onBuy(
        stock.symbol,
        quantity
      );
    } else {
      onSell(
        stock.symbol,
        quantity
      );
    }
  };

  return (
    <div
      style={{
        position: "fixed",
        inset: 0,
        background:
          "rgba(0,0,0,.7)",
        display: "flex",
        alignItems:
          "center",
        justifyContent:
          "center",
        zIndex: 100000,
        padding: "20px"
      }}
      onClick={onClose}
    >

      <div
        className="panel"
        style={{
          width: "100%",
          maxWidth: "500px"
        }}
        onClick={(event) =>
          event.stopPropagation()
        }
      >

        <div className="panel-header">

          <div>

            <h3>
              {stock.name}
            </h3>

            <span
              style={{
                color:
                  "var(--text-secondary)"
              }}
            >
              {stock.symbol} •{" "}
              {stock.exchange}
            </span>

          </div>

          <button
            className="btn-icon"
            onClick={onClose}
          >
            <i className="fas fa-times" />
          </button>

        </div>

        <div className="panel-body">

          <div
            style={{
              textAlign:
                "center",
              marginBottom:
                "25px"
            }}
          >

            <div
              style={{
                fontSize:
                  "32px",
                fontWeight:
                  "700"
              }}
            >
              ₹
              {stock.price.toFixed(
                2
              )}
            </div>

            <div
              className={
                stock.change >=
                0
                  ? "positive"
                  : "negative"
              }
            >
              {stock.change >=
              0
                ? "+"
                : ""}
              {stock.change.toFixed(
                2
              )}{" "}
              (
              {stock.changePercent >=
              0
                ? "+"
                : ""}
              {Number(
                stock.changePercent
              ).toFixed(2)}
              %)
            </div>

          </div>

          <div
            style={{
              display: "flex",
              gap: "10px",
              marginBottom:
                "20px"
            }}
          >

            <button
              className="btn-primary"
              style={{
                flex: 1
              }}
              onClick={() =>
                setAction(
                  "BUY"
                )
              }
            >
              BUY
            </button>

            <button
              className="btn-secondary"
              style={{
                flex: 1
              }}
              onClick={() =>
                setAction(
                  "SELL"
                )
              }
            >
              SELL
            </button>

          </div>

          <label>
            Quantity
          </label>

          <input
            type="number"
            min="1"
            value={quantity}
            onChange={(
              event
            ) =>
              setQuantity(
                event.target.value
              )
            }
            style={{
              width:
                "100%",
              padding:
                "12px",
              marginTop:
                "8px",
              marginBottom:
                "15px",
              borderRadius:
                "6px",
              border:
                "1px solid var(--border-color)",
              background:
                "var(--bg-secondary)",
              color:
                "var(--text-primary)"
            }}
          />

          <div
            style={{
              display:
                "flex",
              justifyContent:
                "space-between",
              marginBottom:
                "20px"
            }}
          >

            <span>
              Estimated Total
            </span>

            <strong>
              ₹
              {total.toLocaleString(
                undefined,
                {
                  maximumFractionDigits:
                    2
                }
              )}
            </strong>

          </div>

          <button
            className="btn-primary"
            style={{
              width:
                "100%",
              marginBottom:
                "10px"
            }}
            onClick={submit}
            disabled={loading}
          >

            {loading ? (
              <>
                <i className="fas fa-spinner fa-spin" />{" "}
                Processing...
              </>
            ) : (
              <>
                <i
                  className={`fas ${
                    action ===
                    "BUY"
                      ? "fa-shopping-cart"
                      : "fa-arrow-up"
                  }`}
                />{" "}
                Confirm{" "}
                {action}
              </>
            )}

          </button>

          <button
            className="btn-secondary"
            style={{
              width:
                "100%"
            }}
            onClick={
              isInWatchlist
                ? onRemoveWatchlist
                : onAddWatchlist
            }
          >

            <i className="fas fa-star" />{" "}

            {isInWatchlist
              ? "Remove from Watchlist"
              : "Add to Watchlist"}

          </button>

        </div>
      </div>
    </div>
  );
}

function formatMarketCap(value) {
  const number =
    Number(value || 0);

  if (
    number >=
    1000000000000
  ) {
    return (
      "₹" +
      (
        number /
        1000000000000
      ).toFixed(2) +
      "T"
    );
  }

  if (
    number >=
    1000000000
  ) {
    return (
      "₹" +
      (
        number /
        1000000000
      ).toFixed(2) +
      "B"
    );
  }

  if (
    number >=
    1000000
  ) {
    return (
      "₹" +
      (
        number /
        1000000
      ).toFixed(2) +
      "M"
    );
  }

  return (
    "₹" +
    number.toLocaleString()
  );
}

export default App;
